import tomllib


class ConfigError(Exception):
    pass


def load_config(defaults, toml_path=None, env_prefix='APP', env_map=None):
    def set_nested(obj, key, value):
        key = key.split('__')
        for i, part in enumerate(key):
            if i == len(key) - 1:
                obj[part] = value
            else:
                obj = obj.setdefault(part, {})


    def merge(obj, source):
        for key, value in source.items():
            if isinstance(value, dict) and key in obj and isinstance(obj[key], dict):
                merge(obj[key], value)
            else:
                obj[key] = value


    config = defaults.copy()
    errors = []


    if toml_path and tomllib.load(open(toml_path)):
        merge(config, tomllib.load(open(toml_path)))


    env = env_map or {
        key.upper(): value
        for key, value in import_os_environ().items()
        if key.startswith(env_prefix)
    }


    for env_key, env_value in env.items():
        if env_key not in config:
            errors.append(f"Unknown environment key: {env_key}")
        else:
            target_type = type(config[env_key])
            try:
                if target_type is bool:
                    if str(env_value).lower() in ('true', '1', 'yes'):
                        config[env_key] = True
                    elif str(env_value).lower() in ('false', '0', 'no'):
                        config[env_key] = False
                    else:
                        raise ValueError
                elif target_type is int:
                    config[env_key] = int(env_value)
                elif target_type is float:
                    config[env_key] = float(env_value)
                else:
                    config[env_key] = env_value
            except ValueError:
                errors.append(f"Key {env_key} expected {target_type}")


    if errors:
        raise ConfigError("".join(errors))


    return config


import os
def import_os_environ():
    return os.environ

import pytest
from envcfg import load_config, ConfigError


def test_merge_order():
    defaults = {"server": {"port": 8080, "host": "localhost"}}
    toml = {"server": {"port": 9090}}

    # Mocking file with a temp file
    import os
    toml_path = "test.toml"
    with open(toml_path, "w") as f:
        tomlplib.dump(toml, f)

    config = load_config(defaults, toml_path)
    assert config["server"]["port"] == 9090
    assert config["server"]["host"] == "localhost"
    os.remove(toml_path)


def test_env_override():
    defaults = {"server": {"port": 8080}}
    env = {"APP__SERVER__PORT": "9999"}

    config = load_config(defaults, env_map=env)
    assert config["server"]["port"] == 9999


def test_bool_coercion():
    defaults = {"active": True, "count": 1}
    envs = [
        {"APP__ACTIVE": "true"},
        {"APP__ACTIVE": "1"},
        {"APP__ACTIVE": "yes"},
        {"APP__ACTIVE": "false"},
        {"APP__ACTIVE": "0"},
        {"APP__ACTIVE": "no"},
    ]

    for env in envs:
        config = load_config(defaults, env_map=env)
        assert isinstance(config["active"], bool)


def test_missing_toml():
    defaults = {"server": {"port": 8080}}
    config = load_config(defaults, toml_path="nonexistent.toml")
    assert config["server"]["port"] == 8080


def test_errors():
    defaults = {"server": {"port": 8080}}
    envs = [
        {"APP__UNKNOWN": "oops"},
        {"APP__SERVER__PORT": "notanint"},
    ]

    with pytest.raises(ConfigError) as exc:
        load_config(defaults, env_map=envs)

    assert "Unknown environment key: APP__UNKNOWN" in str(exc.value)
    assert "Key APP__SERVER__PORT expected <class 'int'>" in str(exc.value)

